from playwright.sync_api import sync_playwright
import json

widths = [(1920,930),(1440,900),(1280,800),(1024,768)]
with sync_playwright() as p:
    b = p.chromium.launch()
    out = {}
    for w,h in widths:
        pg = b.new_page(viewport={'width':w,'height':h})
        rows = []
        for n in [1,2,3,4]:
            pg.goto(f'http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html?preview=thesis-0{n}')
            pg.wait_for_timeout(900)
            r = pg.evaluate('''() => {
              const ts = document.querySelector('.ts:not([style*=\"--in:0\"])') || document.querySelector('.js .ts');
              // find the currently visible (fully in) sentence: --in ~1 and --out ~0
              const all = Array.from(document.querySelectorAll('.ts'));
              let active = null;
              for (const el of all) {
                const cs = getComputedStyle(el);
                const clip = cs.clipPath;
                if (clip === 'none' || clip.includes('inset(0px 0px 0px 0px)') || clip === 'inset(0px)') { active = el; break; }
              }
              if (!active) active = all[all.length-1];
              const photoBox = document.querySelector('.thesis-photo-box');
              const rTs = active.getBoundingClientRect();
              const rPhoto = photoBox.getBoundingClientRect();
              const railRight = getComputedStyle(document.querySelector('.thesis-stage')).paddingRight;
              return {
                fontSize: getComputedStyle(active).fontSize,
                tsTop: rTs.top, photoTop: rPhoto.top, photoWidth: rPhoto.width, photoRight: rPhoto.right,
                innerWidth: window.innerWidth,
                borderRightVisible: getComputedStyle(photoBox).borderRightWidth,
              };
            }''')
            rows.append({'n': n, **r})
        out[f'{w}x{h}'] = rows
        pg.close()
    b.close()
    print(json.dumps(out, indent=1))
"

