from playwright.sync_api import sync_playwright

widths = [(1920,930),(1440,900),(1280,800),(1024,768)]
with sync_playwright() as p:
    b = p.chromium.launch()
    for w,h in widths:
        pg = b.new_page(viewport={'width':w,'height':h})
        pg.goto('http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html')
        pg.wait_for_timeout(700)
        r = pg.evaluate('''() => {
          const out = {};
          for (const [label, sel] of [['calyx','.case--calyx .case-text'],['horai','.case--horai .case-text']]) {
            const el = document.querySelector(sel);
            const stage = el.closest('.case-stage');
            const stageRect = stage.getBoundingClientRect();
            const stageStyle = getComputedStyle(stage);
            const padTop = parseFloat(stageStyle.paddingTop)||0, padBottom = parseFloat(stageStyle.paddingBottom)||0;
            const usableTop = stageRect.top + padTop, usableBottom = stageRect.bottom - padBottom;
            // check every .cs li (all stacked, grid-area 1/1) for overflow
            const lis = Array.from(el.querySelectorAll('.cs'));
            let maxBottom = -Infinity, minTop = Infinity;
            for (const li of lis) {
              const r = li.getBoundingClientRect();
              maxBottom = Math.max(maxBottom, r.bottom);
              minTop = Math.min(minTop, r.top);
            }
            const titleRect = el.querySelector('.case-title').getBoundingClientRect();
            out[label] = {
              stageTop: Math.round(stageRect.top), usableTop: Math.round(usableTop), usableBottom: Math.round(usableBottom),
              titleTop: Math.round(titleRect.top), stepsMaxBottom: Math.round(maxBottom), stepsMinTop: Math.round(minTop),
              overflowBottom: Math.round(maxBottom - usableBottom), overflowTop: Math.round(usableTop - minTop)
            };
          }
          return out;
        }''')
        print(w, r)
        pg.close()
    b.close()
"

