    const left = Math.max(0, rect.left), right = Math.min(vw, rect.right);
    const top = Math.max(0, rect.top), bottom = Math.min(vh, rect.bottom);
    if (left >= right || top >= bottom) continue;
    for (let iy = 0; iy < 3; iy++) {
      for (let ix = 0; ix < 3; ix++) {
